08343     {
08344         IMGUI_DEMO_MARKER("Examples/Console");
08345         ClearLog();
08346         memset(InputBuf, 0, sizeof(InputBuf));
08347         HistoryPos = -1;
08348 
08349         // "CLASSIFY" is here to provide the test case where "C"+[tab] completes to "CL" and display multiple matches.
