08391     {
08392         ImGui::SetNextWindowSize(ImVec2(520, 600), ImGuiCond_FirstUseEver);
08393         if (!ImGui::Begin(title, p_open))
08394         {
08395             ImGui::End();
08396             return;
08397         }
08398 
08399         // As a specific feature guaranteed by the library, after calling Begin() the last Item represent the title bar.
08400         // So e.g. IsItemHovered() will return true when hovering the title bar.
08401         // Here we create a context menu only available from the title bar.
08402         if (ImGui::BeginPopupContextItem())
08403         {
08404             if (ImGui::MenuItem("Close Console"))
08405                 *p_open = false;
08406             ImGui::EndPopup();
08407         }
08408 
08409         ImGui::TextWrapped(
08410             "This example implements a console with basic coloring, completion (TAB key) and history (Up/Down keys). A more elaborate "
08411             "implementation may want to store entries along with extra data such as timestamp, emitter, etc.");
08412         ImGui::TextWrapped("Enter 'HELP' for help.");
08413 
08414         // TODO: display items starting from the bottom
08415 
08416         if (ImGui::SmallButton("Add Debug Text"))  { AddLog("%d some text", Items.Size); AddLog("some more text"); AddLog("display very important message here!"); }
08417         ImGui::SameLine();
08418         if (ImGui::SmallButton("Add Debug Error")) { AddLog("[error] something went wrong"); }
08419         ImGui::SameLine();
08420         if (ImGui::SmallButton("Clear"))           { ClearLog(); }
08421         ImGui::SameLine();
08422         bool copy_to_clipboard = ImGui::SmallButton("Copy");
08423         //static float t = 0.0f; if (ImGui::GetTime() - t > 0.02f) { t = ImGui::GetTime(); AddLog("Spam %f", t); }
08424 
08425         ImGui::Separator();
08426 
08427         // Options menu
08428         if (ImGui::BeginPopup("Options"))
08429         {
08430             ImGui::Checkbox("Auto-scroll", &AutoScroll);
08431             ImGui::EndPopup();
08432         }
08433 
08434         // Options, Filter
08435         ImGui::SetNextItemShortcut(ImGuiMod_Ctrl | ImGuiKey_O, ImGuiInputFlags_Tooltip);
08436         if (ImGui::Button("Options"))
08437             ImGui::OpenPopup("Options");
08438         ImGui::SameLine();
08439         Filter.Draw("Filter (\"incl,-excl\") (\"error\")", 180);
08440         ImGui::Separator();
08441 
08442         // Reserve enough left-over height for 1 separator + 1 input text
08443         const float footer_height_to_reserve = ImGui::GetStyle().ItemSpacing.y + ImGui::GetFrameHeightWithSpacing();
08444         if (ImGui::BeginChild("ScrollingRegion", ImVec2(0, -footer_height_to_reserve), ImGuiChildFlags_NavFlattened, ImGuiWindowFlags_HorizontalScrollbar))
08445         {
08446             if (ImGui::BeginPopupContextWindow())
08447             {
08448                 if (ImGui::Selectable("Clear")) ClearLog();
08449                 ImGui::EndPopup();
08450             }
08451 
08452             // Display every line as a separate entry so we can change their color or add custom widgets.
08453             // If you only want raw text you can use ImGui::TextUnformatted(log.begin(), log.end());
08454             // NB- if you have thousands of entries this approach may be too inefficient and may require user-side clipping
08455             // to only process visible items. The clipper will automatically measure the height of your first item and then
08456             // "seek" to display only items in the visible area.
08457             // To use the clipper we can replace your standard loop:
08458             //      for (int i = 0; i < Items.Size; i++)
08459             //   With:
08460             //      ImGuiListClipper clipper;
08461             //      clipper.Begin(Items.Size);
08462             //      while (clipper.Step())
08463             //         for (int i = clipper.DisplayStart; i < clipper.DisplayEnd; i++)
08464             // - That your items are evenly spaced (same height)
08465             // - That you have cheap random access to your elements (you can access them given their index,
08466             //   without processing all the ones before)
08467             // You cannot this code as-is if a filter is active because it breaks the 'cheap random-access' property.
08468             // We would need random-access on the post-filtered list.
08469             // A typical application wanting coarse clipping and filtering may want to pre-compute an array of indices
08470             // or offsets of items that passed the filtering test, recomputing this array when user changes the filter,
08471             // and appending newly elements as they are inserted. This is left as a task to the user until we can manage
08472             // to improve this example code!
08473             // If your items are of variable height:
08474             // - Split them into same height items would be simpler and facilitate random-seeking into your list.
08475             // - Consider using manual call to IsRectVisible() and skipping extraneous decoration from your items.
08476             ImGui::PushStyleVar(ImGuiStyleVar_ItemSpacing, ImVec2(4, 1)); // Tighten spacing
08477             if (copy_to_clipboard)
08478                 ImGui::LogToClipboard();
08479             for (const char* item : Items)
08480             {
08481                 if (!Filter.PassFilter(item))
08482                     continue;
08483 
08484                 // Normally you would store more information in your item than just a string.
08485                 // (e.g. make Items[] an array of structure, store color/type etc.)
08486                 ImVec4 color;
08487                 bool has_color = false;
08488                 if (strstr(item, "[error]")) { color = ImVec4(1.0f, 0.4f, 0.4f, 1.0f); has_color = true; }
08489                 else if (strncmp(item, "# ", 2) == 0) { color = ImVec4(1.0f, 0.8f, 0.6f, 1.0f); has_color = true; }
08490                 if (has_color)
08491                     ImGui::PushStyleColor(ImGuiCol_Text, color);
08492                 ImGui::TextUnformatted(item);
08493                 if (has_color)
08494                     ImGui::PopStyleColor();
08495             }
08496             if (copy_to_clipboard)
08497                 ImGui::LogFinish();
08498 
08499             // Keep up at the bottom of the scroll region if we were already at the bottom at the beginning of the frame.
08500             // Using a scrollbar or mouse-wheel will take away from the bottom edge.
08501             if (ScrollToBottom || (AutoScroll && ImGui::GetScrollY() >= ImGui::GetScrollMaxY()))
08502                 ImGui::SetScrollHereY(1.0f);
08503             ScrollToBottom = false;
08504 
08505             ImGui::PopStyleVar();
08506         }
08507         ImGui::EndChild();
08508         ImGui::Separator();
08509 
08510         // Command-line
08511         bool reclaim_focus = false;
08512         ImGuiInputTextFlags input_text_flags = ImGuiInputTextFlags_EnterReturnsTrue | ImGuiInputTextFlags_EscapeClearsAll | ImGuiInputTextFlags_CallbackCompletion | ImGuiInputTextFlags_CallbackHistory;
08513         if (ImGui::InputText("Input", InputBuf, IM_ARRAYSIZE(InputBuf), input_text_flags, &TextEditCallbackStub, (void*)this))
08514         {
08515             char* s = InputBuf;
08516             Strtrim(s);
08517             if (s[0])
08518                 ExecCommand(s);
08519             strcpy(s, "");
08520             reclaim_focus = true;
08521         }
08522 
08523         // Auto-focus on window apparition
08524         ImGui::SetItemDefaultFocus();
08525         if (reclaim_focus)
08526             ImGui::SetKeyboardFocusHere(-1); // Auto focus previous widget
08527 
08528         ImGui::End();
08529     }

08532     {
08533         AddLog("# %s\n", command_line);
08534 
08535         // Insert into history. First find match and delete it so it can be pushed to the back.
08536         // This isn't trying to be smart or optimal.
08537         HistoryPos = -1;
08538         for (int i = History.Size - 1; i >= 0; i--)
08539             if (Stricmp(History[i], command_line) == 0)
08540             {
08541                 ImGui::MemFree(History[i]);
08542                 History.erase(History.begin() + i);
08543                 break;
08544             }
08545         History.push_back(Strdup(command_line));
08546 
08547         // Process command
08548         if (Stricmp(command_line, "CLEAR") == 0)
08549         {
08550             ClearLog();
08551         }
08552         else if (Stricmp(command_line, "HELP") == 0)
08553         {
08554             AddLog("Commands:");
08555             for (int i = 0; i < Commands.Size; i++)
08556                 AddLog("- %s", Commands[i]);
08557         }
08558         else if (Stricmp(command_line, "HISTORY") == 0)
08559         {
08560             int first = History.Size - 10;
08561             for (int i = first > 0 ? first : 0; i < History.Size; i++)
08562                 AddLog("%3d: %s\n", i, History[i]);
08563         }
08564         else
08565         {
08566             AddLog("Unknown command: '%s'\n", command_line);
08567         }
08568 
08569         // On command input, we scroll to bottom even if AutoScroll==false
08570         ScrollToBottom = true;
08571     }

08581     {
08582         //AddLog("cursor: %d, selection: %d-%d", data->CursorPos, data->SelectionStart, data->SelectionEnd);
08583         switch (data->EventFlag)
08584         {
08585         case ImGuiInputTextFlags_CallbackCompletion:
08586             {
08587                 // Example of TEXT COMPLETION
08588 
08589                 // Locate beginning of current word
08590                 const char* word_end = data->Buf + data->CursorPos;
08591                 const char* word_start = word_end;
08592                 while (word_start > data->Buf)
08593                 {
08594                     const char c = word_start[-1];
08595                     if (c == ' ' || c == '\t' || c == ',' || c == ';')
08596                         break;
08597                     word_start--;
08598                 }
08599 
08600                 // Build a list of candidates
08601                 ImVector<const char*> candidates;
08602                 for (int i = 0; i < Commands.Size; i++)
08603                     if (Strnicmp(Commands[i], word_start, (int)(word_end - word_start)) == 0)
08604                         candidates.push_back(Commands[i]);
08605 
08606                 if (candidates.Size == 0)
08607                 {
08608                     // No match
08609                     AddLog("No match for \"%.*s\"!\n", (int)(word_end - word_start), word_start);
08610                 }
08611                 else if (candidates.Size == 1)
08612                 {
08613                     // Single match. Delete the beginning of the word and replace it entirely so we've got nice casing.
08614                     data->DeleteChars((int)(word_start - data->Buf), (int)(word_end - word_start));
08615                     data->InsertChars(data->CursorPos, candidates[0]);
08616                     data->InsertChars(data->CursorPos, " ");
08617                 }
08618                 else
08619                 {
08620                     // Multiple matches. Complete as much as we can..
08621                     // So inputing "C"+Tab will complete to "CL" then display "CLEAR" and "CLASSIFY" as matches.
08622                     int match_len = (int)(word_end - word_start);
08623                     for (;;)
08624                     {
08625                         int c = 0;
08626                         bool all_candidates_matches = true;
08627                         for (int i = 0; i < candidates.Size && all_candidates_matches; i++)
08628                             if (i == 0)
08629                                 c = toupper(candidates[i][match_len]);
08630                             else if (c == 0 || c != toupper(candidates[i][match_len]))
08631                                 all_candidates_matches = false;
08632                         if (!all_candidates_matches)
08633                             break;
08634                         match_len++;
08635                     }
08636 
08637                     if (match_len > 0)
08638                     {
08639                         data->DeleteChars((int)(word_start - data->Buf), (int)(word_end - word_start));
08640                         data->InsertChars(data->CursorPos, candidates[0], candidates[0] + match_len);
08641                     }
08642 
08643                     // List matches
08644                     AddLog("Possible matches:\n");
08645                     for (int i = 0; i < candidates.Size; i++)
08646                         AddLog("- %s\n", candidates[i]);
08647                 }
08648 
08649                 break;
08650             }
08651         case ImGuiInputTextFlags_CallbackHistory:
08652             {
08653                 // Example of HISTORY
08654                 const int prev_history_pos = HistoryPos;
08655                 if (data->EventKey == ImGuiKey_UpArrow)
08656                 {
08657                     if (HistoryPos == -1)
08658                         HistoryPos = History.Size - 1;
08659                     else if (HistoryPos > 0)
08660                         HistoryPos--;
08661                 }
08662                 else if (data->EventKey == ImGuiKey_DownArrow)
08663                 {
08664                     if (HistoryPos != -1)
08665                         if (++HistoryPos >= History.Size)
08666                             HistoryPos = -1;
08667                 }
08668 
08669                 // A better implementation would preserve the data on the current input line along with cursor position.
08670                 if (prev_history_pos != HistoryPos)
08671                 {
08672                     const char* history_str = (HistoryPos >= 0) ? History[HistoryPos] : "";
08673                     data->DeleteChars(0, data->BufTextLen);
08674                     data->InsertChars(0, history_str);
08675                 }
08676             }
08677         }
08678         return 0;
08679     }
